(s, paid) => {
    const [first] = paid;
    if (first !== undefined)
        s.event = first;
}

(s, answers) => {
    const [first] = answers;
    if (first !== undefined)
        s.answer = first;
}

(s, demos) => {
    const [first] = demos;
    if (first !== undefined)
        s.event = first;
}

(s, answers) => {
    const [first] = answers;
    if (first !== undefined)
        s.answer = first;
}

(s, ticks) => {
    const [first] = ticks;
    if (first !== undefined)
        s.instant = first.instant;
}

(s, changes) => {
    const [first] = changes;
    if (first !== undefined)
        s.change = { objectId: first.objectId, version: first.version };
}

(s, ends) => {
    const [first] = ends;
    if (first === undefined)
        return;
    const output = first.output;
    s.result = { reason: first.reason ?? "", paid: output !== null && output.paid === true, amount: output !== null && typeof output.amount === "number" ? output.amount : 0, transferId: output !== null && typeof output.transferId === "string" ? output.transferId : "" };
}

(s, ends) => {
    const [first] = ends;
    if (first === undefined)
        return;
    const output = first.output;
    s.result = { reason: first.reason ?? "", paid: output !== null && output.paid === true, amount: output !== null && typeof output.amount === "number" ? output.amount : 0, transferId: output !== null && typeof output.transferId === "string" ? output.transferId : "" };
}

